import { useEffect } from 'react';
import { VisionCameraWorkletsProxy } from '../../third-party/VisionCameraWorkletsProxy';
export function useExposureUpdater(controller, exposure) {
    useEffect(() => {
        if (controller == null)
            return;
        if (exposure == null)
            return;
        if (typeof exposure === 'number') {
            // number
            controller.setExposureBias(exposure);
            return;
        }
        else {
            // SharedValue<number>
            controller.setExposureBias(exposure.get());
            const listener = VisionCameraWorkletsProxy.bindUIUpdatesToController(exposure, controller, 'setExposureBias');
            return () => listener.remove();
        }
    }, [controller, exposure]);
}
